mapper.select:
SELECT p.id, p.camera_id, c.underpass_id, p.detected_num, p.confidence, p.image_path, p.review_deadline, p.detected_at FROM plate_log p JOIN underpass_camera c ON c.id = p.camera_id JOIN underpass u ON u.id = c.underpass_id WHERE p.review_status = 'PENDING'
AND u.region_id = #{regionId}
AND c.underpass_id = #{underpassId}
ORDER BY p.review_deadline ASC
